mapper.insert:

    /* MessageDao.insertMessage */
    select coalesce(max(m.message_id), -1) + 1 from messages m

/* MessageDao.insertMessage */
insert into messages(message_id, locale, message_key, message_content, created_at)
values (#{messageId}, #{locale}, #{messageKey}, #{messageContent}, now() )

mapper.update:
/* MessageDao.updateMessage */
update messages m
set m.locale = #{locale}
, m.message_key = #{messageKey}
, m.message_content = #{messageContent}
, m.updated_at = now()
where m.message_id = #{messageId}
and m.deleted_at is null

/* MessageDao.deleteMessage */
update messages m
set m.deleted_at = now()
where m.message_id = #{messageId}
and m.deleted_at is null
